mcp:tool-listener.mcp:parameters-schema:
{
	"$schema": "http://json-schema.org/draft-07/schema#",
	"type": "object",
	"properties": {
		"aeropuerto": {
			"type": "string",
			"description": "Aeropuerto AENA donde se deja el coche: código IATA (3 letras, p. ej. MAD) o nombre de la ciudad/aeropuerto"
		},
		"fechaEntrada": {
			"type": "string",
			"description": "Entrada al parking: AAAA-MM-DD o AAAA-MM-DDTHH:mm"
		},
		"fechaSalida": {
			"type": "string",
			"description": "Salida del parking: AAAA-MM-DD o AAAA-MM-DDTHH:mm"
		},
		"correlationId": {
			"type": "string",
			"description": "Identificador de trazabilidad de la petición. Opcional: si la solicitud trae un correlationId, cópialo tal cual"
		}
	},
	"required": [
		"aeropuerto",
		"fechaEntrada",
		"fechaSalida"
	]
}

{
	"$schema": "http://json-schema.org/draft-07/schema#",
	"type": "object",
	"properties": {
		"aeropuerto": {
			"type": "string",
			"description": "Aeropuerto AENA: código IATA (3 letras, p. ej. MAD) o nombre de la ciudad/aeropuerto"
		},
		"opcionId": {
			"type": "string",
			"enum": [
				"EXPRESS",
				"GENERAL",
				"LARGA_ESTANCIA"
			],
			"description": "Opción de parking elegida"
		},
		"fechaEntrada": {
			"type": "string",
			"description": "Entrada al parking: AAAA-MM-DD o AAAA-MM-DDTHH:mm"
		},
		"fechaSalida": {
			"type": "string",
			"description": "Salida del parking: AAAA-MM-DD o AAAA-MM-DDTHH:mm"
		},
		"matricula": {
			"type": "string",
			"description": "Matrícula del coche (opcional)"
		},
		"referencia": {
			"type": "string",
			"description": "Referencia externa, normalmente el localizador de la reserva del vuelo"
		},
		"correlationId": {
			"type": "string",
			"description": "Identificador de trazabilidad de la petición. Opcional: si la solicitud trae un correlationId, cópialo tal cual"
		}
	},
	"required": [
		"aeropuerto",
		"opcionId",
		"fechaEntrada",
		"fechaSalida"
	]
}
